CREATE TABLE dish (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    name VARCHAR(120) NOT NULL,
    description VARCHAR(800) NOT NULL,
    cuisine VARCHAR(80) NOT NULL,
    restaurant_name VARCHAR(120) NOT NULL,
    neighborhood VARCHAR(120) NOT NULL,
    price NUMERIC(8,2) NOT NULL,
    rating NUMERIC(2,1) NOT NULL,
    review_count INTEGER NOT NULL,
    image_url VARCHAR(2048) NOT NULL,
    dietary_tags VARCHAR(255) NOT NULL,
    CONSTRAINT pk_dish PRIMARY KEY (id),
    CONSTRAINT ck_dish_price CHECK (price >= 0),
    CONSTRAINT ck_dish_rating CHECK (rating >= 0 AND rating <= 5),
    CONSTRAINT ck_dish_review_count CHECK (review_count >= 0)
);

CREATE INDEX ix_dish_name ON dish (name);
CREATE INDEX ix_dish_cuisine ON dish (cuisine);

